window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c8d10f81272a9fc0"]={"versions": [{"id": "FIG-c8d10f81272a9fc0", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Steuergeräte-Zustandsmanagements (AUTOSAR Classic Platform, BSW-Ebene). Dargestellt wird die Sequenz <code>Slave Core WakeupRestart Sequence</code> zur Reaktivierung eines Slave-Cores aus dem Schlafmodus bzw. Haltedustand unter Beteiligung des ECU State Managers (<code>EcuM</code>), des Betriebssystems (<code>Os</code>), des Microcontroller-Treibers (<code>Mcu</code>) sowie von Integrationscode (<code>Integration Code</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm definiert vier Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: Zentrale Steuerungsinstanz auf dem jeweiligen Slave-Core.\n</li><li><code>Integration Code</code>: Lebenslinie für kundenspezifischen bzw. plattformspezifischen Integrationscode (in dieser Sequenz inaktiv).\n</li><li><code>«module» Os</code>: AUTOSAR-Betriebssystem mit Schnittstellen <code>DisableAllInterrupts()</code>, <code>EnableAllInterrupts()</code> und <code>ReleaseResource(ResourceType)</code>.\n</li><li><code>«module» Mcu</code>: Microcontroller-Treiber mit der Schnittstelle <code>Mcu_SetMode(Mcu_ModeType)</code>.\n</li></ul>\n<p class=\"fig-p\">Sämtliche Aufrufe sind als synchrone Funktionsaufrufe mit expliziter gestrichelter Antwortnachricht (Return) modelliert; als Ressourcenparameter dient <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code>.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf auf dem Slave-Core nach dem Aufwachen umfasst folgende Schritte:</p>\n<ol class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>DisableAllInterrupts()</code> am <code>Os</code> auf, um die Interruptverarbeitung während des Moduswechsels zu sperren.\n</li><li>Nach Rückkehr ruft <code>EcuM</code> synchron <code>Mcu_SetMode(Mcu_ModeType)</code> am <code>Mcu</code> auf, um den Betriebsmodus des Mikrocontrollers bzw. Cores wiederherzustellen.\n</li><li>Nach Rückkehr des Moduswechsels hebt <code>EcuM</code> die globale Interruptsperre mittels synchronem Aufruf von <code>EnableAllInterrupts()</code> am <code>Os</code> auf.\n</li><li>Abschließend gibt <code>EcuM</code> die systemspezifische Core-Ressource über <code>ReleaseResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code> an das <code>Os</code> frei, wodurch der Slave-Core synchronisiert in den regulären Betrieb übergehen kann.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Implementierungsvorgabe für Mehrkern-Systeme (Multicore) im AUTOSAR BSW-Stack: Der Slave-Core muss vor der Wiederherstellung des MCU-Modus alle Interrupts über das OS sperren und erst danach wieder freigeben. Die Synchronisationsressource <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code> schützt den Zustand des jeweiligen Slave-Cores gegenüber dem Master-Core und darf erst nach vollständiger lokaler Initialisierung/Moduseinstellung freigegeben werden.</p>"}, {"id": "FIG-b77c38c9a9329642", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Steuergeräte-Zustandsmanagements (AUTOSAR Classic Platform, BSW-Ebene). Dargestellt wird die Sequenz <code>Slave Core WakeupRestart Sequence</code> zur Reaktivierung eines Slave-Cores aus dem Schlafmodus bzw. Haltedustand unter Beteiligung des ECU State Managers (<code>EcuM</code>), des Betriebssystems (<code>Os</code>), des Microcontroller-Treibers (<code>Mcu</code>) sowie von Integrationscode (<code>Integration Code</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm definiert fünf Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: Zentrale Steuerungsinstanz auf dem Slave-Core.\n</li><li><code>Integration Code</code>: Kundenspezifischer Integrationscode (inaktiv).\n</li><li><code>«module» Os</code>: AUTOSAR-Betriebssystem mit <code>DisableAllInterrupts()</code>, <code>EnableAllInterrupts()</code> und <code>ReleaseResource(ResourceType)</code>.\n</li><li><code>«module» Mcu</code>: Microcontroller-Treiber mit <code>Mcu_SetMode(Mcu_ModeType)</code>.\n</li><li><code>«module» BswM</code>: BSW Mode Manager mit der Statusschnittstelle <code>BswM_EcuM_CurrentState(EcuM_WakeupStatusType)</code>.\n</li></ul>\n<p class=\"fig-p\">Zusätzlich nutzt <code>EcuM</code> die interne Funktion <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code>. Alle Aufrufe sind als synchrone Meldungen mit Rückkehrpfeil modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Sequenzablauf vollzieht sich wie folgt:</p>\n<ol class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>DisableAllInterrupts()</code> am <code>Os</code> auf.\n</li><li><code>EcuM</code> ruft synchron <code>Mcu_SetMode(Mcu_ModeType)</code> am <code>Mcu</code> auf.\n</li><li><code>EcuM</code> ruft synchron <code>EnableAllInterrupts()</code> am <code>Os</code> auf.\n</li><li><code>EcuM</code> führt einen synchronen internen Aufruf <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code> aus, um nicht mehr aktive Wakeup-Quellen zu deaktivieren.\n</li><li><code>EcuM</code> meldet den Status per synchronem Aufruf <code>BswM_EcuM_CurrentState(ECUM_WKSTATUS_DISABLED)</code> an das <code>BswM</code>.\n</li><li><code>EcuM</code> gibt die Synchronisationsressource über <code>ReleaseResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code> an das <code>Os</code> frei.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Sequenz für Multicore-Systeme ab Release 4.1: Vor der Freigabe der Kernressource <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code> müssen Wakeup-Quellen bereinigt (<code>EcuM_DisableWakeupSources</code>) und der Modusmanager über den Zustand <code>ECUM_WKSTATUS_DISABLED</code> via <code>BswM_EcuM_CurrentState()</code> informiert werden, damit BSW-Modusregeln konsistent triggern können.</p>"}, {"id": "FIG-2d668ebd894a7474", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Steuergeräte-Zustandsmanagements (AUTOSAR Classic Platform, BSW-Ebene). Dargestellt wird die Sequenz <code>Slave Core WakeupRestart Sequence</code> zur Reaktivierung eines Slave-Cores aus dem Schlafmodus bzw. Haltedustand unter Beteiligung des ECU State Managers (<code>EcuM</code>), des Betriebssystems (<code>Os</code>), des Microcontroller-Treibers (<code>Mcu</code>) sowie von Integrationscode (<code>Integration Code</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm definiert fünf Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: Zentrale Steuerungsinstanz auf dem Slave-Core.\n</li><li><code>Integration Code</code>: Kundenspezifischer Integrationscode (inaktiv).\n</li><li><code>«module» Os</code>: AUTOSAR-Betriebssystem mit <code>DisableAllInterrupts()</code>, <code>EnableAllInterrupts()</code> und <code>ReleaseResource(ResourceType)</code>.\n</li><li><code>«module» Mcu</code>: Microcontroller-Treiber mit <code>Mcu_SetMode(Mcu_ModeType)</code>.\n</li><li><code>«module» BswM</code>: BSW Mode Manager mit der Statusschnittstelle <code>BswM_EcuM_CurrentState(EcuM_WakeupStatusType)</code>.\n</li></ul>\n<p class=\"fig-p\">Zusätzlich nutzt <code>EcuM</code> die interne Funktion <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code>. Alle Aufrufe sind als synchrone Meldungen mit Rückkehrpfeil modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Sequenzablauf vollzieht sich wie folgt:</p>\n<ol class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>DisableAllInterrupts()</code> am <code>Os</code> auf.\n</li><li><code>EcuM</code> ruft synchron <code>Mcu_SetMode(Mcu_ModeType)</code> am <code>Mcu</code> auf.\n</li><li><code>EcuM</code> ruft synchron <code>EnableAllInterrupts()</code> am <code>Os</code> auf.\n</li><li><code>EcuM</code> führt einen synchronen internen Aufruf <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code> aus, um nicht mehr aktive Wakeup-Quellen zu deaktivieren.\n</li><li><code>EcuM</code> meldet den Status per synchronem Aufruf <code>BswM_EcuM_CurrentState(ECUM_WKSTATUS_DISABLED)</code> an das <code>BswM</code>.\n</li><li><code>EcuM</code> gibt die Synchronisationsressource über <code>ReleaseResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code> an das <code>Os</code> frei.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Sequenz für Multicore-Systeme ab Release 4.1: Vor der Freigabe der Kernressource <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code> müssen Wakeup-Quellen bereinigt (<code>EcuM_DisableWakeupSources</code>) und der Modusmanager über den Zustand <code>ECUM_WKSTATUS_DISABLED</code> via <code>BswM_EcuM_CurrentState()</code> informiert werden, damit BSW-Modusregeln konsistent triggern können.</p>"}, {"id": "FIG-a83c5223d8f2cffd", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Steuergeräte-Zustandsmanagements (AUTOSAR Classic Platform, BSW-Ebene). Dargestellt wird die Sequenz <code>Slave Core WakeupRestart Sequence</code> zur Reaktivierung eines Slave-Cores aus dem Schlafmodus bzw. Haltedustand unter Beteiligung des ECU State Managers (<code>EcuM</code>), des Betriebssystems (<code>Os</code>), des Microcontroller-Treibers (<code>Mcu</code>) sowie von Integrationscode (<code>Integration Code</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm umfasst vier Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: Steuerungsinstanz des Zustandsmanagements auf dem Slave-Core.\n</li><li><code>Integration Code</code>: Plattformspezifischer Integrationscode mit dem Callout <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code>.\n</li><li><code>«module» Os</code>: AUTOSAR-Betriebssystem mit <code>DisableAllInterrupts()</code>, <code>EnableAllInterrupts()</code> und <code>ReleaseResource(ResourceType)</code>.\n</li><li><code>«module» Mcu</code>: Microcontroller-Treiber mit <code>Mcu_SetMode(Mcu_ModeType)</code>.\n</li></ul>\n<p class=\"fig-p\">Alle Aufrufe erfolgen synchron mit expliziter Rückkehrantwort. Die Lebenslinie <code>BswM</code> ist nicht vorhanden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>DisableAllInterrupts()</code> am <code>Os</code> auf.\n</li><li><code>EcuM</code> ruft synchron <code>Mcu_SetMode(Mcu_ModeType)</code> am <code>Mcu</code> auf.\n</li><li><code>EcuM</code> ruft synchron <code>EnableAllInterrupts()</code> am <code>Os</code> auf.\n</li><li><code>EcuM</code> ruft synchron das Callout <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code> auf der Lebenslinie <code>Integration Code</code> auf.\n</li><li>Nach Rückkehr des Callouts gibt <code>EcuM</code> mittels synchronem Aufruf <code>ReleaseResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code> die OS-Ressource an das <code>Os</code> frei.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Anforderung für die Slave-Core-Aufwachsequenz: Die Deaktivierung der Wakeup-Quellen wird über die Integrationsschnittstelle / das Callout <code>EcuM_DisableWakeupSources</code> an den Integrationscode delegiert, bevor die Synchronisationsressource <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code> an das Betriebssystem freigegeben wird. Eine Benachrichtigung des BswM entfällt an dieser Stelle auf dem Slave-Core.</p>"}, {"id": "FIG-8628763654c2d176", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Steuergeräte-Zustandsmanagements (AUTOSAR Classic Platform, BSW-Ebene). Dargestellt wird die Sequenz <code>Slave Core WakeupRestart Sequence</code> zur Reaktivierung eines Slave-Cores aus dem Schlafmodus bzw. Haltedustand unter Beteiligung des ECU State Managers (<code>EcuM</code>), des Betriebssystems (<code>Os</code>), des Microcontroller-Treibers (<code>Mcu</code>) sowie von Integrationscode (<code>Integration Code</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm umfasst vier Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: Steuerungsinstanz des Zustandsmanagements auf dem Slave-Core.\n</li><li><code>Integration Code</code>: Plattformspezifischer Integrationscode mit dem Callout <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code>.\n</li><li><code>«module» Os</code>: AUTOSAR-Betriebssystem mit <code>DisableAllInterrupts()</code>, <code>EnableAllInterrupts()</code> und <code>ReleaseResource(ResourceType)</code>.\n</li><li><code>«module» Mcu</code>: Microcontroller-Treiber mit <code>Mcu_SetMode(Mcu_ModeType)</code>.\n</li></ul>\n<p class=\"fig-p\">Alle Aufrufe erfolgen synchron mit expliziter Rückkehrantwort. Die Lebenslinie <code>BswM</code> ist nicht vorhanden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>DisableAllInterrupts()</code> am <code>Os</code> auf.\n</li><li><code>EcuM</code> ruft synchron <code>Mcu_SetMode(Mcu_ModeType)</code> am <code>Mcu</code> auf.\n</li><li><code>EcuM</code> ruft synchron <code>EnableAllInterrupts()</code> am <code>Os</code> auf.\n</li><li><code>EcuM</code> ruft synchron das Callout <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code> auf der Lebenslinie <code>Integration Code</code> auf.\n</li><li>Nach Rückkehr des Callouts gibt <code>EcuM</code> mittels synchronem Aufruf <code>ReleaseResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code> die OS-Ressource an das <code>Os</code> frei.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Anforderung für die Slave-Core-Aufwachsequenz: Die Deaktivierung der Wakeup-Quellen wird über die Integrationsschnittstelle / das Callout <code>EcuM_DisableWakeupSources</code> an den Integrationscode delegiert, bevor die Synchronisationsressource <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code> an das Betriebssystem freigegeben wird. Eine Benachrichtigung des BswM entfällt an dieser Stelle auf dem Slave-Core.</p>"}, {"id": "FIG-16d11cd1226bb4e6", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Steuergeräte-Zustandsmanagements (AUTOSAR Classic Platform, BSW-Ebene). Dargestellt wird die Sequenz <code>Slave Core WakeupRestart Sequence</code> zur Reaktivierung eines Slave-Cores aus dem Schlafmodus bzw. Haltedustand unter Beteiligung des ECU State Managers (<code>EcuM</code>), des Betriebssystems (<code>Os</code>), des Microcontroller-Treibers (<code>Mcu</code>) sowie von Integrationscode (<code>Integration Code</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm umfasst vier Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: Steuerungsinstanz des Zustandsmanagements auf dem Slave-Core.\n</li><li><code>Integration Code</code>: Plattformspezifischer Integrationscode mit dem Callout <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code>.\n</li><li><code>«module» Os</code>: AUTOSAR-Betriebssystem mit <code>DisableAllInterrupts()</code>, <code>EnableAllInterrupts()</code> und <code>ReleaseResource(ResourceType)</code>.\n</li><li><code>«module» Mcu</code>: Microcontroller-Treiber mit <code>Mcu_SetMode(Mcu_ModeType)</code>.\n</li></ul>\n<p class=\"fig-p\">Alle Aufrufe erfolgen synchron mit expliziter Rückkehrantwort. Die Lebenslinie <code>BswM</code> ist nicht vorhanden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>DisableAllInterrupts()</code> am <code>Os</code> auf.\n</li><li><code>EcuM</code> ruft synchron <code>Mcu_SetMode(Mcu_ModeType)</code> am <code>Mcu</code> auf.\n</li><li><code>EcuM</code> ruft synchron <code>EnableAllInterrupts()</code> am <code>Os</code> auf.\n</li><li><code>EcuM</code> ruft synchron das Callout <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code> auf der Lebenslinie <code>Integration Code</code> auf.\n</li><li>Nach Rückkehr des Callouts gibt <code>EcuM</code> mittels synchronem Aufruf <code>ReleaseResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code> die OS-Ressource an das <code>Os</code> frei.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Anforderung für die Slave-Core-Aufwachsequenz: Die Deaktivierung der Wakeup-Quellen wird über die Integrationsschnittstelle / das Callout <code>EcuM_DisableWakeupSources</code> an den Integrationscode delegiert, bevor die Synchronisationsressource <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code> an das Betriebssystem freigegeben wird. Eine Benachrichtigung des BswM entfällt an dieser Stelle auf dem Slave-Core.</p>"}, {"id": "FIG-10011f1e2ba2c63d", "releases": ["R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des Steuergeräte-Zustandsmanagements (AUTOSAR Classic Platform, BSW-Ebene). Dargestellt wird die Sequenz <code>Slave Core WakeupRestart Sequence</code> zur Reaktivierung eines Slave-Cores aus dem Schlafmodus bzw. Haltedustand unter Beteiligung des ECU State Managers (<code>EcuM</code>), des Betriebssystems (<code>Os</code>), des Microcontroller-Treibers (<code>Mcu</code>) sowie von Integrationscode (<code>Integration Code</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Sequenzdiagramm umfasst vier Lebenslinien:</p>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: Steuerungsinstanz des Zustandsmanagements auf dem Slave-Core.\n</li><li><code>Integration Code</code>: Plattformspezifischer Integrationscode mit dem Callout <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code>.\n</li><li><code>«module» Os</code>: AUTOSAR-Betriebssystem mit <code>DisableAllInterrupts()</code>, <code>EnableAllInterrupts()</code> und <code>ReleaseResource(ResourceType)</code>.\n</li><li><code>«module» Mcu</code>: Microcontroller-Treiber mit <code>Mcu_SetMode(Mcu_ModeType)</code>.\n</li></ul>\n<p class=\"fig-p\">Alle Aufrufe erfolgen synchron mit expliziter Rückkehrantwort. Die Lebenslinie <code>BswM</code> ist nicht vorhanden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\"><li><code>EcuM</code> ruft synchron <code>DisableAllInterrupts()</code> am <code>Os</code> auf.\n</li><li><code>EcuM</code> ruft synchron <code>Mcu_SetMode(Mcu_ModeType)</code> am <code>Mcu</code> auf.\n</li><li><code>EcuM</code> ruft synchron <code>EnableAllInterrupts()</code> am <code>Os</code> auf.\n</li><li><code>EcuM</code> ruft synchron das Callout <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code> auf der Lebenslinie <code>Integration Code</code> auf.\n</li><li>Nach Rückkehr des Callouts gibt <code>EcuM</code> mittels synchronem Aufruf <code>ReleaseResource(RES_AUTOSAR_ECUM_&lt;core#&gt;)</code> die OS-Ressource an das <code>Os</code> frei.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Anforderung für die Slave-Core-Aufwachsequenz: Die Deaktivierung der Wakeup-Quellen wird über die Integrationsschnittstelle / das Callout <code>EcuM_DisableWakeupSources</code> an den Integrationscode delegiert, bevor die Synchronisationsressource <code>RES_AUTOSAR_ECUM_&lt;core#&gt;</code> an das Betriebssystem freigegeben wird. Eine Benachrichtigung des BswM entfällt an dieser Stelle auf dem Slave-Core.</p>"}], "trans": [{"from": "FIG-c8d10f81272a9fc0", "to": "FIG-b77c38c9a9329642", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ergänzung der Lebenslinie <code>«module» BswM</code>.\n</li><li>Neuer synchroner Selbstaufruf <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code> am <code>EcuM</code> nach <code>EnableAllInterrupts()</code>.\n</li><li>Neuer synchroner Aufruf <code>BswM_EcuM_CurrentState(ECUM_WKSTATUS_DISABLED)</code> von <code>EcuM</code> an <code>BswM</code> vor <code>ReleaseResource()</code>.\n</li></ul>"}, {"from": "FIG-b77c38c9a9329642", "to": "FIG-2d668ebd894a7474", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2d668ebd894a7474", "to": "FIG-a83c5223d8f2cffd", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Entfernung der Lebenslinie <code>«module» BswM</code>.\n</li><li>Entfernung des Aufrufs <code>BswM_EcuM_CurrentState(ECUM_WKSTATUS_DISABLED)</code>.\n</li><li>Der Aufruf <code>EcuM_DisableWakeupSources(EcuM_WakeupSourceType)</code> erfolgt nun als Callout von <code>EcuM</code> an die Lebenslinie <code>Integration Code</code> statt als lokaler Selbstaufruf.\n</li></ul>"}, {"from": "FIG-a83c5223d8f2cffd", "to": "FIG-8628763654c2d176", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8628763654c2d176", "to": "FIG-16d11cd1226bb4e6", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-16d11cd1226bb4e6", "to": "FIG-10011f1e2ba2c63d", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
